-- --- ORAIMO AUDIO (12 products) ---
('oraimo-spacebuds-pro', 'Oraimo SpaceBuds Pro ANC True Wireless Earbuds', 'audio', 35000, 35000, 28500, 80, 0.048, '/assets/products/oraimo-spacebuds-pro.jpg', 'Oraimo SpaceBuds Pro deliver premium audio with 10mm dynamic drivers, Active Noise Cancellation up to 35dB, and transparency mode for situational awareness. Bluetooth 5.3, 40-hour total battery life (8 hours earbuds + 32 hours case), and quad-mic ENC for crystal-clear calls in noisy environments. 60ms low-latency gaming mode, IPX5 sweat and water resistance, and wireless charging case. Ergonomic in-ear design with three ear tip sizes for all-day comfort. Oraimo Sound app with customizable EQ, touch controls, and Find My Earbuds. The ultimate value in ANC earbuds from Nigeria''s favorite audio brand.', 1, 1718400000, 1, 28500, '/assets/products/oraimo-spacebuds-pro.jpg', 31350, 4.6, 1, 'Oraimo', 1, 1),

('oraimo-spacebuds-neo', 'Oraimo SpaceBuds Neo True Wireless Earbuds', 'audio', 17798, 17798, 14200, 120, 0.045, '/assets/products/oraimo-spacebuds-neo.jpg', 'The Oraimo SpaceBuds Neo are the best-selling TWS earbuds in Nigeria, and for good reason. 13mm dynamic drivers with Oraimo Bass+ technology deliver deep, thumping low-end that brings Afrobeats, hip-hop, and dancehall to life. Bluetooth 5.3, 36-hour total battery (8 hours earbuds + 28 hours case), and dual-mic ENC noise reduction for calls. 60ms game mode, IPX5 water resistance, and smart touch controls. The compact charging case features USB-C fast charging (10 minutes = 2 hours playtime) and a sleek matte finish. Google Fast Pair for instant Android connection. Oraimo''s legendary reliability and customer support make these the go-to choice for millions of Nigerian music lovers.', 1, 1718400000, 1, 14200, '/assets/products/oraimo-spacebuds-neo.jpg', 15620, 4.5, 1, 'Oraimo', 1, 1),

('oraimo-freepods-lite', 'Oraimo FreePods Lite True Wireless Earbuds', 'audio', 12000, 12000, 9500, 150, 0.04, '/assets/products/oraimo-freepods-lite.jpg', 'Oraimo FreePods Lite make wireless audio accessible to everyone. 10mm drivers deliver clear, balanced sound. Bluetooth 5.3, 28-hour total battery (6.5 hours earbuds + 21.5 hours case), and ENC call noise reduction. IPX4 splash resistance, touch controls, and USB-C charging. Ultra-lightweight 3.8g per earbud with semi-in-ear design for extended comfort. Available in Black and White. The perfect first wireless earbuds or affordable backup pair.', 1, 1718400000, 1, 9500, '/assets/products/oraimo-freepods-lite.jpg', 10450, 4.5, 1, 'Oraimo', 1, 1),

('oraimo-freepods-pro', 'Oraimo FreePods Pro Wireless Earbuds', 'audio', 25000, 25000, 20000, 100, 0.045, '/assets/products/oraimo-freepods-pro.jpg', 'Oraimo FreePods Pro upgrade to premium features with ANC up to 30dB, 11mm dynamic drivers, and transparency mode. Bluetooth 5.3, 35-hour total battery (7.5 hours ANC off), and quad-mic ENC. IPX5, wireless charging case, 55ms gaming mode, and Oraimo Sound app support. Rich bass, clear mids, and detailed highs for an immersive listening experience.', 1, 1718400000, 1, 20000, '/assets/products/oraimo-freepods-pro.jpg', 22000, 4.6, 1, 'Oraimo', 1, 0),

('oraimo-boompop', 'Oraimo BoomPop Wireless Over-Ear Headphones', 'audio', 18500, 18500, 14800, 75, 0.25, '/assets/products/oraimo-boompop.jpg', 'Oraimo BoomPop wireless headphones deliver Oraimo''s signature bass-forward sound in an over-ear design. 40mm dynamic drivers, Bluetooth 5.3, and up to 45 hours of battery life. Foldable design with memory foam ear cushions and adjustable headband for long-wearing comfort. Built-in microphone for calls, 3.5mm AUX port for wired use, and USB-C charging. Available in Black, Blue, and Red. Perfect for immersive music, movies, and gaming at an unbeatable price.', 1, 1718400000, 1, 14800, '/assets/products/oraimo-boompop.jpg', 16280, 4.4, 0, 'Oraimo', 1, 0),

('oraimo-rhythm-nb200', 'Oraimo Rhythm NB200 Neckband Wireless Earphones', 'audio', 9500, 9500, 7500, 110, 0.035, '/assets/products/oraimo-rhythm-nb200.jpg', 'Oraimo Rhythm NB200 neckband earphones combine convenience with long battery life. 10mm drivers, Bluetooth 5.3, and magnetic earbuds that snap together to pause music and answer calls. Up to 22 hours playback, USB-C fast charging (10 min = 3 hours), and IPX5 sweat resistance. Flexible neckband with premium silicone coating for all-day comfort. Ideal for workouts, commuting, and hands-free calls.', 1, 1718400000, 1, 7500, '/assets/products/oraimo-rhythm-nb200.jpg', 8250, 4.4, 0, 'Oraimo', 1, 0),

('oraimo-soundbar-bt', 'Oraimo Portable Bluetooth Soundbar 20W', 'audio', 22000, 22000, 17800, 55, 0.42, '/assets/products/oraimo-soundbar-bt.jpg', 'The Oraimo Portable Bluetooth Soundbar delivers room-filling 20W audio through dual full-range drivers and dual passive radiators. Bluetooth 5.3, AUX input, USB playback, and microSD card slot. Built-in 2000mAh battery provides up to 12 hours of playback. IPX6 water resistance handles splashes and rain. Compact with carrying strap — perfect for parties, outdoor events, and movie nights.', 1, 1718400000, 1, 17800, '/assets/products/oraimo-soundbar-bt.jpg', 19580, 4.3, 0, 'Oraimo', 0, 0),

('oraimo-neckband-pro', 'Oraimo Neckband Pro ANC Wireless Earphones', 'audio', 18500, 18500, 14800, 85, 0.04, '/assets/products/oraimo-neckband-pro.jpg', 'Oraimo Neckband Pro elevates neckband audio with Active Noise Cancellation up to 28dB and 13mm bass-enhanced drivers. Bluetooth 5.3, 28-hour battery (ANC off), and dual-mic ENC. Magnetic earbuds with auto-pause/play, IPX5 rating, and USB-C fast charging. The comfortable neckband with reflective strip for visibility. Premium features in a practical form factor.', 1, 1718400000, 1, 14800, '/assets/products/oraimo-neckband-pro.jpg', 16280, 4.5, 0, 'Oraimo', 0, 1),

-- --- ORAIMO POWER BANKS (8 products) ---
('oraimo-powerbox-10000', 'Oraimo PowerBox 10000mAh Power Bank USB-C', 'power', 9500, 9500, 7500, 140, 0.21, '/assets/products/oraimo-powerbox-10000.jpg', 'Oraimo PowerBox 10000mAh is the ultimate slim portable charger. 18W PD fast charging via USB-C and dual USB-A outputs (charge 2 devices simultaneously). LED battery indicator, 12-layer safety protection including overcharge, overdischarge, and short circuit prevention. Compact 210g design with textured anti-slip body in Black or White. Charges most smartphones 2-2.5 times. Nigeria''s best-selling slim power bank trusted for daily reliability.', 1, 1718400000, 1, 7500, '/assets/products/oraimo-powerbox-10000.jpg', 8250, 4.5, 1, 'Oraimo', 1, 0),

('oraimo-powerbox-20000', 'Oraimo PowerBox 20000mAh Power Bank 22.5W', 'power', 18500, 18500, 14800, 110, 0.38, '/assets/products/oraimo-powerbox-20000.jpg', 'Oraimo PowerBox 20000mAh with 22.5W fast charging features triple ports (USB-C + dual USB-A) to charge three devices simultaneously. Digital LED display shows exact remaining percentage. USB-C supports input and output. 12-layer safety system, aircraft-safe 74Wh capacity, and textured anti-slip body. Fast recharges itself at 18W in 6 hours. Trusted by Nigerian travelers, students, and professionals for reliable multi-device charging.', 1, 1718400000, 1, 14800, '/assets/products/oraimo-powerbox-20000.jpg', 16280, 4.6, 1, 'Oraimo', 1, 0),

('oraimo-powerbox-30000', 'Oraimo PowerBox 30000mAh Power Bank 22.5W', 'power', 24500, 24500, 19800, 90, 0.45, '/assets/products/oraimo-powerbox-30000.jpg', 'Oraimo PowerBox 30000mAh delivers massive capacity for extended trips and heavy users. 22.5W fast charging via USB-C and triple USB-A outputs charge 4 devices at once. Digital percentage display, 18W fast recharging, and 12-layer protection. Charges a typical smartphone 6-7 times. Aircraft-safe design, textured finish for grip. The ultimate high-capacity power solution from Nigeria''s most trusted power brand.', 1, 1718400000, 1, 19800, '/assets/products/oraimo-powerbox-30000.jpg', 21780, 4.5, 1, 'Oraimo', 1, 1),

('oraimo-powerhub-10000-slim', 'Oraimo PowerHub 10000mAh Slim Built-in Cable Power Bank', 'power', 12500, 12500, 9800, 100, 0.20, '/assets/products/oraimo-powerhub-10000-slim.jpg', 'Oraimo PowerHub 10000mAh Slim features built-in Lightning and USB-C cables — no need to carry separate cables. 20W PD fast charging, additional USB-C and USB-A ports for third device. Ultra-slim 14mm profile fits pockets easily. Digital display, 12-layer protection, and 220g weight. The ultimate convenience power bank with integrated cables for iPhone and Android users.', 1, 1718400000, 1, 9800, '/assets/products/oraimo-powerhub-10000-slim.jpg', 10780, 4.5, 0, 'Oraimo', 0, 1),

('oraimo-powerhub-20000-cable', 'Oraimo PowerHub 20000mAh Built-in Cable Power Bank', 'power', 22000, 22000, 17800, 80, 0.39, '/assets/products/oraimo-powerhub-20000-cable.jpg', 'Oraimo PowerHub 20000mAh with built-in Lightning and USB-C cables plus additional USB-C and USB-A ports. 22.5W PD fast charging, digital display, and 12-layer safety. 18W fast recharging. The integrated cable design eliminates cable clutter — perfect for travelers and daily commuters.', 1, 1718400000, 1, 17800, '/assets/products/oraimo-powerhub-20000-cable.jpg', 19580, 4.5, 0, 'Oraimo', 0, 0),

